      // -> respawn IN PLACE at its spawn point: the old top-respawn on age expiry teleported every
      // particle out of its cluster within one lifetime, evaporating the clump structure in space.
      if (pos.y < -3.5){ pos = dustSpawn(seed); pos.y = 24.0 + seed.z * 10.0; age = 0.0; }
